sys_variable_value.value:
(function execute(inputs, outputs) {
    if (String(inputs.status_code) !== '200') {
        throw new Error('Xero GET Time failed: ' + inputs.status_code + ' ' + inputs.response_body);
    }
    var body = JSON.parse(inputs.response_body);
    var dates = [];
    (body.items || []).forEach(function (item) {
        if (item.dateUtc) {
            dates.push(item.dateUtc.substring(0, 10));
        }
    });
    outputs.existing_dates = dates.join(',');
})(inputs, outputs);

